class Food(object):
    def __init__(self, n, v, w):
        self.name = n
        self.value = v
        self.calories = w

    def getValue(self):
        return self.value

    def getCost(self):
        return self.calories

    def density(self):
        return self.getValue()/self.cost()

    def __str__(self):
        return self.name + ':<' + str(self.value)\n        + ', ' + str(self.calories) + '>'
```

